// === Tab: mySketch ===
//for #wccChallenge theme: pointillism. Personal goals- nothing but points, 50 lines or less Ended up w Mark Rothko vs Seurat but JS animation
let mover=0
let waterColors=['#5d809a','#70a0b8','#8aa0b8','#436d79']
let sandColors=['#af967a','#bd9f80','#bfa28c','#826d51','#bba385']
let skyColors=['#6ea7dc','#84b3dd','#5d98d1','#96b0cd','#99b8d3']
let simplex

function setup() {	
	createCanvas(windowHeight *0.75, windowHeight);
	rs=random(1000)
	simplex = new OpenSimplexNoise(Date.now());
}

function draw() {
	randomSeed(rs)
	background(255)

	//clouds
	for(let y=0; y<=height/2; y+=5){
		for(let x=0; x<=width+5; x+=5){
			stroke(random(skyColors))
	 strokeWeight(map(noise(y/50, (x+mover)/100), 0, 1, 0, 8))
		point(x, y)
		}
	}
	mover+=0.9

	//sand
	for(let y=height*0.7; y<height; y+=5){
		for(let x=0; x<=width; x+=5){
			stroke(random(sandColors))
		strokeWeight(noise(x, y)*5);
			point(x- noise(y/10)*2, y- noise(x/20, y/20)*10)
		}
	}

	//water
	let power=3
	for(let y=height/2; y<height *0.75; y+=5){
		for(let x=0; x<=width+5; x+=5){
			stroke(random(waterColors))
		strokeWeight(4.5)
			yer=map(simplex.noise3D(x/200, (y+ sin(mover/30)*power)/80, mover/50), -1, 1, -power+sin(mover/10), power+sin(mover/10))
			point(x, y + yer)	
		}
		power+=2
	}	
}

function windowResized() {
  resizeCanvas(windowHeight *0.75, windowHeight);
}

